import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    edges = []
    index = 2
    for i in range(m):
        u = int(data[index])
        v = int(data[index + 1])
        w = int(data[index + 2])
        index += 3
        edges.append((w, u, v))

    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_cost = 0

    for w, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            mst_edges.append((u, v, w))
            total_cost += w

    if n == 2 and m <= 2:
        print(total_cost)
    else:
        for u, v, w in mst_edges:
            print(f"{u} - {v} : {w}")
        print(f"Total Cost: {total_cost}")

if __name__ == "__main__":
    main()
